# this sitting's ledger, every claim LABELED (logic/MIDDOT.md's codes; World/step9/CLAIM_LABELS.md), a machine check where the ink allows —
# every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS: the check is the word's LONGEST PIECE WHOLE
# (never a prefix fragment; the floor four code points) — NEVER 6:4's "hear" or "one" (the store drops their large letters). Claim IDs DV06-
# (6:1-25). Written once (no file may exist; the ID prefix checked absent from every existing manifest and unit). Every source cite is checked
# against the ledger's CITE INDEX before a byte is written, and every CITE INDEX name must be used by a claim. Sitting 3's form.
import json, os, re, sqlite3, glob, subprocess
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()
DATE = '2026-09-17'
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    assert (c, v) != (6, 4), 'never 6:4 — the store drops its large letters'
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Devarim {r}' for r in rows)
def piska(p, n, skip=()): return [f'{p}:{r}' for r in range(1, n + 1) if r not in skip]
led = open(f'{ROOT}/logic/oral_triage/deu_06_vaetchanan_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M))
assert len(CI) == 97, len(CI)

